from fractions import Fraction as F
def ev(a,b):
    m={a:b,b:a}; g=lambda x:F(m.get(x,x))
    return g(15)+g(5)*g(8)-g(72)/g(4)+g(16)*g(3)
opts={'A':(15,16),'B':(5,4),'C':(8,4),'D':(5,3)}
assert [k for k,v in opts.items() if ev(*v)==101]==['D']

def val(a,b,c,d,e,f,g):
    return a+b*c-d/e+f*g
base=[15,5,8,72,4,16,3]
def sw(x,y):
    l=[y if v==x else x if v==y else v for v in base]
    return val(*l)
opts={'A':(15,16),'B':(5,4),'C':(8,4),'D':(5,3)}
ok={k:abs(sw(*v)-101)<1e-9 for k,v in opts.items()}
assert ok['D'] and not ok['A'] and not ok['B'] and not ok['C']

